begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) select ('22000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'generation-'||n||'@example.invalid' from generate_series(1,4)n;
insert into public.memberships(user_id) select id from auth.users where email like 'generation-%@example.invalid';
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) select user_id,'Generation pilot','KPAO','licensed' from public.memberships where user_id::text like '22000000-%';
insert into public.flights(id,owner_id,departure_airport,destination_airport,departure_at,departure_timezone,aircraft_description,pilot_places,visibility) values('22020000-0000-4000-8000-000000000001','22000000-0000-4000-8000-000000000001','KPAO','KSQL',now()+interval '2 days','UTC','C172',2,'PRIVATE');
insert into public.flight_recipients(flight_id,user_id) select '22020000-0000-4000-8000-000000000001',user_id from public.memberships where user_id::text in ('22000000-0000-4000-8000-000000000002','22000000-0000-4000-8000-000000000003');
create function pg_temp.actor(n integer) returns text language sql as $$select set_config('request.jwt.claims',json_build_object('sub',('22000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated')::text,true);$$;
create temporary table receipts(kind text,receipt jsonb);
grant all on receipts to authenticated;
set local role authenticated;
select pg_temp.actor(2);
insert into receipts values('submitted',public.submit_flight_interest('22020000-0000-4000-8000-000000000001','Private introductory canary'));
reset role;
select is((select receipt->>'code' from receipts where kind='submitted'),'submitted','Eligible interest submitted');
select is((select count(*)::integer from public.notifications),1,'Submission atomically creates one notification');
select is((select recipient_id::text from public.notifications where event_type='request_received'),'22000000-0000-4000-8000-000000000001','Submission notifies actual owner');
select is((select request_id::text from public.notifications where event_type='request_received'),(select receipt->>'requestId' from receipts where kind='submitted'),'Request target is the authorized operation source');
create temporary table original_notification as select * from public.notifications;
set local role authenticated;
select pg_temp.actor(2);
select is(public.submit_flight_interest('22020000-0000-4000-8000-000000000001','Different retry note')->>'code','already_requested','Pending retry is a no-op');
select pg_temp.actor(4);
select is(public.submit_flight_interest('22020000-0000-4000-8000-000000000001')->>'code','flight_unavailable','Unselected private member cannot request');
select throws_ok($$select public.decide_flight_request('22020000-0000-4000-8000-000000000001',(select (receipt->>'requestId')::uuid from receipts where kind='submitted'),'accepted')$$,'42501',null,'Foreign decision denied');
reset role;
select results_eq('select * from public.notifications order by id','select * from original_notification order by id','Retries and denied operations preserve original notification');
set local role authenticated;
select pg_temp.actor(1);
select is(public.decide_flight_request('22020000-0000-4000-8000-000000000001',(select (receipt->>'requestId')::uuid from receipts where kind='submitted'),'accepted')->>'code','decided','Owner accepts');
reset role;
select is((select count(*)::integer from public.notifications),2,'Acceptance atomically adds one notification');
select is((select recipient_id::text from public.notifications where event_type='request_accepted'),'22000000-0000-4000-8000-000000000002','Acceptance notifies requester');
create temporary table accepted_notifications as select * from public.notifications;
set local role authenticated;
select pg_temp.actor(1);
select is(public.decide_flight_request('22020000-0000-4000-8000-000000000001',(select (receipt->>'requestId')::uuid from receipts where kind='submitted'),'accepted')->>'code','already_decided','Acceptance retry confirms history');
select is(public.decide_flight_request('22020000-0000-4000-8000-000000000001',(select (receipt->>'requestId')::uuid from receipts where kind='submitted'),'declined')->>'code','request_conflict','Opposing terminal decision rejected');
reset role;
select results_eq('select * from public.notifications order by id','select * from accepted_notifications order by id','Acceptance retries preserve identity and chronology');
set local role authenticated;
select pg_temp.actor(2);
insert into receipts values('conversation',jsonb_build_object('id',public.get_or_create_flight_conversation((select (receipt->>'requestId')::uuid from receipts where kind='submitted'))));
select public.send_conversation_message((select (receipt->>'id')::uuid from receipts where kind='conversation'),'22050000-0000-4000-8000-000000000001','Private message canary');
reset role;
select is((select count(*)::integer from public.notifications),3,'Message atomically adds one notification');
select is((select recipient_id::text from public.notifications where message_id='22050000-0000-4000-8000-000000000001'),'22000000-0000-4000-8000-000000000001','Requester message notifies only owner');
create temporary table message_notifications as select * from public.notifications;
set local role authenticated;
select pg_temp.actor(2);
select public.send_conversation_message((select (receipt->>'id')::uuid from receipts where kind='conversation'),'22050000-0000-4000-8000-000000000001','Private message canary');
select throws_ok($$select public.send_conversation_message((select (receipt->>'id')::uuid from receipts where kind='conversation'),'22050000-0000-4000-8000-000000000001','Changed retry')$$,'22023',null,'Message identity conflict rejected');
select pg_temp.actor(4);
select throws_ok($$select public.send_conversation_message((select (receipt->>'id')::uuid from receipts where kind='conversation'),'22050000-0000-4000-8000-000000000002','Foreign message')$$,'42501',null,'Foreign message denied');
reset role;
select results_eq('select * from public.notifications order by id','select * from message_notifications order by id','Message retries and denials preserve notification identity/time');
set local role authenticated;
select pg_temp.actor(1);
select public.send_conversation_message((select (receipt->>'id')::uuid from receipts where kind='conversation'),'22050000-0000-4000-8000-000000000002','Reciprocal canary');
reset role;
select is((select recipient_id::text from public.notifications where message_id='22050000-0000-4000-8000-000000000002'),'22000000-0000-4000-8000-000000000002','Owner message notifies only requester');
select ok((select bool_and(to_jsonb(n)::text not like '%canary%') from public.notifications n),'No private content copied');
-- Test-only failure injection proves each source and notification share a transaction.
create function pg_temp.reject_notification() returns trigger language plpgsql as $$begin raise exception 'Owned notification failure' using errcode='23514';end;$$;
create trigger generation_failure before insert on public.notifications for each row execute function pg_temp.reject_notification();
set local role authenticated;
select pg_temp.actor(1);
select throws_ok($$select public.send_conversation_message((select (receipt->>'id')::uuid from receipts where kind='conversation'),'22050000-0000-4000-8000-000000000003','Rollback canary')$$,'23514',null,'Message persistence failure propagates');
select pg_temp.actor(3);
select throws_ok($$select public.submit_flight_interest('22020000-0000-4000-8000-000000000001')$$,'23514',null,'Request persistence failure propagates');
reset role;
select is((select count(*)::integer from public.messages where id='22050000-0000-4000-8000-000000000003'),0,'Failed notification rolls message back');
select is((select count(*)::integer from public.flight_requests where requester_id='22000000-0000-4000-8000-000000000003'),0,'Failed notification rolls request back');
drop trigger generation_failure on public.notifications;
set local role authenticated;
select pg_temp.actor(2);
select public.withdraw_flight_request('22020000-0000-4000-8000-000000000001',(select (receipt->>'requestId')::uuid from receipts where kind='submitted'));
select throws_ok($$select public.send_conversation_message((select (receipt->>'id')::uuid from receipts where kind='conversation'),'22050000-0000-4000-8000-000000000004','Closed canary')$$,'42501',null,'Closed conversation creates no message');
select public.submit_flight_interest('22020000-0000-4000-8000-000000000001');
reset role;
select is((select count(*)::integer from public.notifications where event_type='request_received'),2,'Same-record eligible resubmission creates new occurrence');
create trigger generation_failure before insert on public.notifications for each row execute function pg_temp.reject_notification();
set local role authenticated;
select pg_temp.actor(1);
select throws_ok($$select public.decide_flight_request('22020000-0000-4000-8000-000000000001',(select (receipt->>'requestId')::uuid from receipts where kind='submitted'),'accepted')$$,'23514',null,'Acceptance notification failure propagates outside source eligibility handler');
reset role;
select is((select status::text from public.flight_requests where id=(select (receipt->>'requestId')::uuid from receipts where kind='submitted')),'pending','Failed acceptance notification rolls status back');
select is((select count(*)::integer from public.notifications where event_type='request_accepted'),1,'Failed acceptance adds no notification');
drop trigger generation_failure on public.notifications;
set local role authenticated;
select pg_temp.actor(1);
select public.decide_flight_request('22020000-0000-4000-8000-000000000001',(select (receipt->>'requestId')::uuid from receipts where kind='submitted'),'accepted');
select pg_temp.actor(3);
insert into receipts values('decline',public.submit_flight_interest('22020000-0000-4000-8000-000000000001'));
select pg_temp.actor(1);
select public.decide_flight_request('22020000-0000-4000-8000-000000000001',(select (receipt->>'requestId')::uuid from receipts where kind='decline'),'declined');
reset role;
select is((select count(*)::integer from public.notifications where event_type='request_accepted'),2,'Reacceptance creates a distinct event; decline creates none');
select is((select count(*)::integer from public.notifications),7,'Only three approved event kinds generated across successful occurrences');
select * from finish();
rollback;
